import Link from "next/link";
import { getCaseStudiesSlugs, getCaseStudiesMeta } from "@/lib/caseStudies";

/** case-studies index — lists every MDX item. Generated by the Webflow Cloner agent. */
export default function CaseStudiesIndex() {
  const items = getCaseStudiesSlugs().map(getCaseStudiesMeta)
    .sort((a, b) => (b.date ?? "").localeCompare(a.date ?? ""));
  return (
    <main style={{ maxWidth: 880, margin: "0 auto", padding: "4rem 1.25rem" }}>
      <h1>case-studies</h1>
      <ul style={{ listStyle: "none", padding: 0, display: "grid", gap: 24 }}>
        {items.map((it) => (
          <li key={it.slug}>
            <Link href={`/case-studies/${it.slug}`}>
              <h2>{it.title}</h2>
              {it.excerpt ? <p>{it.excerpt}</p> : null}
            </Link>
          </li>
        ))}
      </ul>
    </main>
  );
}
